async function getWithPER(key, compute, ttl, beta = 1.0) {
  const raw = await redis.get(key);
  if (raw) {
    const { value, expiry, delta } = JSON.parse(raw);
    const ttlRemaining = expiry - Date.now() / 1000;
    const probability = Math.exp(-delta * beta * Math.log(ttlRemaining / ttl));
    if (Math.random() > probability) return value;
  }
  const lock = await redis.set('lock:' + key, '1', 'NX', 'EX', 5);
  if (!lock) { await sleep(50); return getWithPER(key, compute, ttl, beta); }
  const start = Date.now();
  const value = await compute();
  const delta = (Date.now() - start) / 1000;
  await redis.set(key, JSON.stringify({ value, expiry: Date.now()/1000 + ttl, delta }), 'EX', ttl + 10);
  await redis.del('lock:' + key);
  return value;
}

